import{_ as t,o as s,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-2-platform-statistics-overview/report3_spec_en.md","filePath":"feature/admin-management/3-10-2-platform-statistics-overview/report3_spec_en.md"}'),r={name:"feature/admin-management/3-10-2-platform-statistics-overview/report3_spec_en.md"};function o(a,e,l,c,d,p){return s(),i("div",null,[...e[0]||(e[0]=[n("<p><strong>3.10.2 Platform Statistics Overview</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an Administrator (ADMIN) accesses the administrative dashboard home at route /admin/dashboard.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. System administrator monitoring operational performance, user growth, and platform revenue.</li><li><strong>Purpose</strong>: Display successful-login activity, user growth, FLAGGED accounts, active strikes and financial indicators with explicit definitions.</li><li><strong>Interface</strong>: Platform Statistics Overview Dashboard (SCR-ADM-02), featuring 4 KPI metric cards, user acquisition growth chart, monthly revenue breakdown chart, subscription plan distribution chart, and top active agencies table.</li><li><strong>Data Processing</strong>: Verify ADMIN; aggregate login events, post/activity counts, active strike state and reconciled payments. Cache for up to 15 minutes by filters, timezone and ranking metric; return asOf and period boundaries.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Platform Statistics Overview Dashboard (SCR-ADM-02, responsive grid layout):</p><ul><li>Left/Header: Admin navigation, period filters and timezone selector UTC / Asia/Ho_Chi_Minh (default).</li><li>Center: KPI cards: total users / successful-login users in trailing 30 days, FLAGGED users, active YELLOW/ORANGE/RED strikes, gross receipts. Growth, receipts and plan-distribution charts; Top 5 Agency table with separate ranking selectors for posts, business activity and revenue. Show the metric and period for each ranking.</li><li>Buttons: Button &quot;Refresh Data&quot; (clears Redis cache and reloads), Button &quot;Custom Date Range&quot;, Button &quot;Export PDF Report&quot;.</li><li>Footer: Last synchronization time, selected timezone and stale/error indicator.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: None (defaults to trailing 12-month period).</li><li><strong>Input optional</strong>: period, startDate, endDate, timezone (UTC or Asia/Ho_Chi_Minh), agencyRankBy (POSTS, ACTIVITY, REVENUE).</li><li><strong>System data</strong>: totalUsers, activeUsers30d, flaggedUsersCount, activeStrikeCounts, grossReceipts, refunds, netReceipts, topAgencies, asOf, timezone.</li><li><strong>Output</strong>: Aggregated platform statistics JSON payload with HTTP status code 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-65</strong>: Platform statistics are restricted to ADMIN.</li><li><strong>BR-65</strong>: activeUsers30d counts distinct users with a successful login in the trailing 30 days. Failed logins and token refresh alone do not count.</li><li><strong>BR-65</strong>: Provide all three Agency ranking views: post count, business activity count and revenue for the selected period; do not invent a weighted composite score. The technical plan must map the existing post, activity-event and payment attribution sources explicitly.</li><li><strong>BR-94</strong>: Active strike counters use FR 3.10.5 eligibility and clean-period state, not a createdAt &gt;= now−30d filter. Show converted/pardoned/expired history separately.</li><li><strong>BR-60</strong>: MRR is the monthly-normalized value of active paid subscriptions after applicable discounts; annual plans contribute annual price / 12. ARR = MRR × 12. Gross receipts include successful subscription and one-off AI Credit payments in the period. Show refunds separately; net receipts = gross receipts − refunds. AI Credits are excluded from MRR. Refunds change MRR only when subscription value/status changes; never deduct them twice.</li><li><strong>BR-65</strong>: Reporting stores timestamps in UTC and supports UTC or Asia/Ho_Chi_Minh (default). Resolve date boundaries and daily/monthly buckets in the selected timezone; include timezone in responses, exports and cache keys.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>User does not possess ADMIN role permissions → Display: MSG39</li><li>Custom date range yields no transaction or operational records → Display: MSG122</li><li>Data refresh request frequency exceeds rate limiting threshold → Display: MSG48</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin opens SCR-ADM-02; system verifies ADMIN authority.</li><li>Select period, timezone and one of three Agency ranking metrics.</li><li>Return fresh cached aggregates or calculate using the same filter and timezone boundaries.</li><li>Render KPIs, charts, rankings and asOf; retain filter context for PDF export.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: If user does not possess ADMIN role, system blocks access and displays MSG39.</li><li>5.a1: If selected date range contains no operational data, system displays MSG122.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Aggregated statistics data is rendered visually on Admin interface.</li><li>Newly computed metrics payload is cached in Redis with a 15-minute TTL.</li></ul>",14)])])}const m=t(r,[["render",o]]);export{g as __pageData,m as default};
